package in.finseq.insurance;
import android.os.*;import android.view.*;import android.widget.*;import org.json.*;
public class AttendanceLeaveActivity extends FinseqActivity{
 EditText from,to,reason;Spinner type;Button submit;
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout root=Ui.column(this);Ui.appHeader(root,this,"Leave Request");LinearLayout body=Ui.contentColumn(this);root.addView(body);type=new Spinner(this);String[] types={"Casual Leave","Sick Leave","Privilege Leave","Unpaid Leave","Work From Home","On Duty"};type.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,types));from=Ui.input(this,"From date YYYY-MM-DD");to=Ui.input(this,"To date YYYY-MM-DD");reason=Ui.input(this,"Reason");submit=Ui.greenButton(this,"Submit Leave Request");submit.setOnClickListener(v->send());body.addView(Ui.sub(this,"Request goes to Admin/Manager approval. Server time is authoritative."));body.addView(type);body.addView(from);body.addView(to);body.addView(reason);body.addView(submit);Ui.setScreen(this,root,5);}
 void send(){submit.setEnabled(false);Ui.run(this,()->{try{JSONObject b=new JSONObject().put("leave_type",String.valueOf(type.getSelectedItem())).put("date_from",from.getText().toString().trim()).put("date_to",to.getText().toString().trim()).put("reason",reason.getText().toString().trim());JSONObject r=ApiClient.post(this,"/api/attendance/leave",b);Ui.ui(this,()->{Ui.toast(this,r.optString("message","Leave request submitted"));finish();});}catch(Exception e){Ui.ui(this,()->{submit.setEnabled(true);Ui.toast(this,e.getMessage());});}});}
}